// Wallet IDs. Every account has a permanent uint32 ID: its position in
// GAME's `wallets` table. Per-player storage maps are
// keyed by that ID and most events carry it instead of an address, so a reader resolves the
// viewer's address to its ID ONCE (Game `walletIdOf_g3120`) and IDs back to addresses through the
// table itself. Cache lifetimes follow the account's identity:
//   - ID -> address is permanent: every element holds its account key, and a loan seizure keeps
//     the borrower's key (it only adds the lender's ID in bits 160..191). The site shows the key and
//     does not follow seizures to the lender: that would re-read every displayed row each snapshot.
//   - address -> ID is cached only for one block snapshot: liquidation clears the default ID. Zero (not registered yet) is re-read every time: the
//     first paying transaction registers the wallet.
// Protocol IDs 1-3 (VAULT, SDGNRS, GNRUS) are ordinary table rows written by Game's constructor.

import { CURRENT_SCHEMA_HASH } from './schema.js';

const ADDRESS_MASK = (1n << 160n) - 1n;
let idCache = new WeakMap();      // `${game}:${address}` -> id (nonzero only)
let addressHints = new WeakMap(); // Reverse getter hints belong only to their source snapshot.
const addressCache = new Map(); // `${game}:${id}` -> { address, group? }
const addressFlights = new Map(); // Same permanent lookup shared across concurrent snapshots.
const registries = new Map(); // One disk load and batched writer per deployment/schema.

// Keyed by chain id too: test fixtures (and a chain switch) reuse contract addresses.
const gameKey = s => `${s.client.chain?.readSchema ?? CURRENT_SCHEMA_HASH}:${s.client.chain?.id ?? ''}:${s.client.address('GAME')}`;
const lower = value => String(value ?? '').toLowerCase();
export const isWalletAddress = value => /^0x[0-9a-f]{40}$/i.test(String(value ?? ''));
const validId = id => Number.isSafeInteger(id) && id > 0 && id <= 0xffffffff;
const validCheckpoint = block => Number.isSafeInteger(block?.number) && block.number >= 0 && /^0x[0-9a-f]{64}$/i.test(block.hash ?? '');
const persistentSnapshot = s => validCheckpoint(s.block) && typeof s.verify === 'function' && typeof s.client.header === 'function';

function saveRegistry(state) {
  if (state.scheduled) return;
  state.scheduled = true;
  // A Multicall batch can finish hundreds of identities together. Serialize
  // that wave once; event-store coalesces the eventual IndexedDB write too.
  queueMicrotask(() => {
    state.scheduled = false;
    if (registries.get(state.key) !== state) return;
    state.store.writeArtifact(state.artifact, { groups: [...state.groups.values()].map(group => ({
      block: group.block, hash: group.hash, rows: [...group.rows],
    })) });
  });
}

async function registry(s) {
  const key = gameKey(s);
  let state = registries.get(key);
  if (!state) {
    state = { key, artifact: `wallet-registry-v1:${key}`, groups: new Map(), store: null, scheduled: false, ready: null };
    registries.set(key, state);
    state.ready = (async () => {
      // Dynamic import avoids the client -> wallets -> event-store cycle.
      state.store = await import('./event-store.js');
      const saved = await state.store.readArtifact(state.artifact);
      if (registries.get(key) !== state || !Array.isArray(saved?.groups)) return;
      for (const row of saved.groups) {
        if (!validCheckpoint({ number: row?.block, hash: row?.hash }) || !Array.isArray(row.rows)) continue;
        const group = { block: row.block, hash: row.hash, rows: new Map(), proofs: new WeakMap(), invalid: false };
        for (const pair of row.rows) {
          if (!Array.isArray(pair) || !validId(pair[0]) || !isWalletAddress(pair[1]) || BigInt(pair[1]) === 0n) continue;
          const address = lower(pair[1]);
          group.rows.set(pair[0], address);
          addressCache.set(`${key}:${pair[0]}`, { address, group });
        }
        if (group.rows.size) state.groups.set(`${group.block}:${group.hash}`, group);
      }
    })();
  }
  await state.ready;
  return state;
}

function discardGroup(state, group) {
  group.invalid = true;
  state.groups.delete(`${group.block}:${group.hash}`);
  for (const id of group.rows.keys()) {
    const key = `${state.key}:${id}`;
    if (addressCache.get(key)?.group === group) addressCache.delete(key);
  }
  saveRegistry(state);
}

async function verifyGroup(s, state, group) {
  if (group.invalid || group.block > s.block.number) return false;
  const generation = s.client.readGeneration;
  const settled = s.client.isSettled?.(group.block) === true;
  let proof = group.proofs.get(s.client);
  // Settled checkpoints share the client's existing finality policy. Their
  // proof survives new heads, but transaction/reorg invalidation still forces
  // a new check. Recent checkpoints are checked once per observed head.
  if (!proof || proof.generation !== generation || proof.head !== s.block.hash && !(proof.settled && settled)) {
    proof = { generation, head: s.block.hash, settled, promise: null };
    group.proofs.set(s.client, proof);
    proof.promise = (async () => {
      const linked = s.client.linksTo?.(s.block, group.block, group.hash);
      let canonical;
      if (linked === true || group.block === s.block.number && group.hash === s.block.hash) {
        await s.verify();
        canonical = true;
      } else {
        // Do not reuse a snapshot's header(number) memo after invalidation:
        // it may contain the old fork. Every row shares this one proof.
        canonical = linked === false ? false : (await s.client.header(group.block)).hash === group.hash;
      }
      if (generation !== s.client.readGeneration) return verifyGroup(s, state, group);
      if (!canonical) discardGroup(state, group);
      return canonical;
    })();
    proof.promise.catch(() => { if (group.proofs.get(s.client) === proof) group.proofs.delete(s.client); });
  }
  return proof.promise;
}

function rememberAddress(s, state, id, address) {
  let group;
  if (state) {
    const checkpoint = `${s.block.number}:${s.block.hash}`;
    group = state.groups.get(checkpoint);
    if (!group) {
      group = { block: s.block.number, hash: s.block.hash, rows: new Map(), proofs: new WeakMap(), invalid: false };
      state.groups.set(checkpoint, group);
    }
    group.rows.set(id, address);
    group.proofs.set(s.client, { generation: s.client.readGeneration, head: s.block.hash,
      settled: s.client.isSettled?.(group.block) === true, promise: Promise.resolve(true) });
    saveRegistry(state);
  }
  addressCache.set(`${gameKey(s)}:${id}`, { address, group });
}

/** The wallet ID of `address` on the snapshot's deployment; 0 when it has not registered. */
export async function walletIdOf_g3120(s, address) {
  if (!isWalletAddress(address)) return 0;
  const key = lower(address);
  let ids = idCache.get(s);
  if (!ids) { ids = new Map(); idCache.set(s, ids); }
  if (ids.has(key)) return ids.get(key);
  const id = Number(await s.call('GAME', 'walletIdOf_g3120', [lower(address)]));
  if (id) {
    ids.set(key, id);
    let hints = addressHints.get(s);
    if (!hints) { hints = new Map(); addressHints.set(s, hints); }
    hints.set(id, key);
  }
  return id;
}

/** Raw wallet-table element of `id` (0n for an unallocated ID). */
async function walletElement(s, id) {
  try { return BigInt(await s.field('GAME', 'wallets', id)); }
  catch (error) { if (/out of bounds/i.test(String(error?.message))) return 0n; throw error; }
}

/**
 * The address an ID stands for: its account key (an acquired account keeps its former borrower's
 * key). null for 0 or an unknown ID.
 */
export async function walletAddressOf(s, id) {
  const n = Number(id ?? 0);
  if (!validId(n)) return null;
  const hint = addressHints.get(s)?.get(n);
  if (hint) return hint;
  const state = persistentSnapshot(s) ? await registry(s) : null;
  const key = `${gameKey(s)}:${n}`;
  const cached = addressCache.get(key);
  if (cached && (!cached.group || state && await verifyGroup(s, state, cached.group))) return cached.address;
  // A historical snapshot cannot borrow an identity first observed in its
  // future; that ID might not have been allocated yet.
  const future = addressFlights.get(key)?.snapshot.block?.number > s.block?.number;
  const flightKey = future ? `${key}:${s.block.hash}` : key;
  const pending = addressFlights.get(flightKey);
  if (pending) {
    const address = await pending.promise;
    if (address || pending.snapshot === s) return address;
    // The first snapshot may predate this ID's registration. Absence is never
    // permanent: a newer snapshot must get its own chance to read the row.
    return walletAddressOf(s, n);
  }
  const flight = { snapshot: s, promise: null };
  flight.promise = (async () => {
    const address = (await walletElement(s, n)) & ADDRESS_MASK;
    if (address === 0n) return null;
    // A shared answer may outlive its source route. Verify it before publishing
    // the permanent identity to other snapshots or the completed cache.
    await s.verify?.();
    const out = '0x' + address.toString(16).padStart(40, '0');
    if (addressFlights.get(flightKey) === flight && (!state || registries.get(state.key) === state)) rememberAddress(s, state, n, out);
    return out;
  })().finally(() => {
    if (addressFlights.get(flightKey) === flight) addressFlights.delete(flightKey);
  });
  addressFlights.set(flightKey, flight);
  return flight.promise;
}

/** Resolve many IDs at once (reads coalesce into the snapshot's multicall). Map id -> address|null. */
export async function walletAddresses(s, ids) {
  const unique = [...new Set([...ids].map(Number).filter(n => Number.isSafeInteger(n) && n > 0))];
  const pairs = await Promise.all(unique.map(async id => [id, await walletAddressOf(s, id)]));
  return new Map(pairs);
}

/** The storage/view key for a player: its wallet ID (0 = no state yet). */
export async function playerKey(s, address) {
  return walletIdOf_g3120(s, address);
}

/** Tests: forget every cached resolution. */
export function clearWalletCacheForTests() {
  idCache = new WeakMap(); addressHints = new WeakMap(); addressCache.clear(); addressFlights.clear(); registries.clear();
}
